use serde::{Deserialize, Serialize};

use crate::content::{Bytes, Chunk};
use crate::error::Result;
use crate::ids::{ByteRange, BytesId, ContentId, EntityId, RelPath};
use crate::store::Store;

/// Accessor/static roles are `Kind` variants so `(parent, kind, name)` stays unique
/// without folding `"get "` into the stored name (which would render `get get path()`).
#[derive(Clone, Copy, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, Debug)]
pub enum Kind {
    Fn,
    Struct,
    Enum,
    Union,
    Trait,
    Impl,
    Const,
    Static,
    Mod,
    TypeAlias,
    Macro,
    JsFunction,
    JsClass,
    JsMethod,
    JsGetter,
    JsSetter,
    JsField,
    JsStaticMethod,
    JsStaticField,
    JsDeclarator,
    JsStaticBlock,
    Opaque,
}

#[derive(Clone, PartialEq, Eq, PartialOrd, Ord, Hash, Serialize, Deserialize, Debug)]
/// What makes an entity the same one across re-parses and merges. Nested items are
/// unique under their parent; file-level items (`parent: None`) are unique within their
/// file, so `file` is set exactly then. Two files may each have a `fn hex32`.
pub struct SigKey {
    pub parent: Option<EntityId>,
    pub file: Option<RelPath>,
    pub kind: Kind,
    pub name: String,
}

#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug)]
pub struct EntityRecord {
    pub name: String,
    pub kind: Kind,
    pub parent: Option<EntityId>,
    pub file: RelPath,
    pub ordinal: u32,
    pub content: ContentId,
    pub bytes: BytesId,
}

/// File tail after the last entity — or the whole of a file svc has no language for —
/// as a content-addressed blob shared by every snapshot that has the same bytes; `None`
/// when nothing follows the last entity. Roots are derived from `Snapshot.entities`
/// (parent is None, same file, ordinal-sorted) so they cannot drift.
#[derive(Clone, PartialEq, Eq, Serialize, Deserialize, Debug, Default)]
pub struct FileRecord {
    pub trailing: Option<BytesId>,
}

impl FileRecord {
    /// Store `tail` as a one-literal blob and point at it; empty tails are `None`.
    pub fn from_tail(store: &dyn Store, tail: &[u8]) -> Result<Self> {
        if tail.is_empty() {
            return Ok(Self::default());
        }
        let blob = Bytes::new(
            tail.to_vec(),
            vec![Chunk::Literal(ByteRange {
                start: 0,
                end: tail.len() as u32,
            })],
            Vec::new(),
        )?;
        Ok(Self {
            trailing: Some(store.put_bytes_blob(&blob)?),
        })
    }

    /// The tail's bytes, fetched from `store`.
    pub fn tail(&self, store: &dyn Store) -> Result<Vec<u8>> {
        match self.trailing {
            None => Ok(Vec::new()),
            Some(id) => Ok(store.get_bytes_blob(id)?.src().to_vec()),
        }
    }
}

impl EntityRecord {
    pub fn sig_key(&self) -> SigKey {
        SigKey::new(self.parent, &self.file, self.kind, self.name.clone())
    }
}

impl SigKey {
    pub fn new(parent: Option<EntityId>, file: &RelPath, kind: Kind, name: String) -> Self {
        Self {
            parent,
            file: parent.is_none().then(|| file.clone()),
            kind,
            name,
        }
    }
}

impl Kind {
    pub fn is_synthetic_named(self) -> bool {
        matches!(self, Kind::Impl | Kind::JsStaticBlock)
    }
}

crates/svc-core/tests/file_tail_blob.rs.Text:
//! A file svc has no language for, and the bytes after a source file's last entity, live
//! in the store as one content-addressed blob per distinct content — not inline in every
//! snapshot. Two snapshots with the same Cargo.lock share the id; the snapshot's own
//! encoding does not grow with the file.
use std::collections::BTreeMap;

use svc_core::engine::{render, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::store::MemStore;

#[test]
fn opaque_file_bytes_are_one_shared_blob_outside_the_snapshot() {
    let store = MemStore::new();
    let langs = rust_langs();
    let lock = RelPath::new("Cargo.lock").unwrap();
    let lib = RelPath::new("src/lib.rs").unwrap();
    let big = vec![b'x'; 1 << 20];
    let mut files = BTreeMap::new();
    files.insert(lock.clone(), big.clone());
    files.insert(lib.clone(), b"fn a() {}\n".to_vec());
    let change = ChangeId::new();
    let s1 = snapshot_files(&store, &langs, &files, None, change).unwrap();
    files.insert(lib.clone(), b"fn a() {}\nfn b() {}\n".to_vec());
    let s2 = snapshot_files(&store, &langs, &files, Some(&s1), change).unwrap();

    let id1 = s1.files[&lock].trailing.expect("a tail");
    assert_eq!(s2.files[&lock].trailing, Some(id1), "same bytes, same blob");
    let encoded = postcard::to_allocvec(&s2).unwrap();
    assert!(encoded.len() < 64 * 1024, "snapshot carries the 1 MiB file inline: {} bytes", encoded.len());
    assert_eq!(render(&s2, &store, &langs, false).unwrap().files[&lock], big);
    assert_eq!(s2.files[&lib].tail(&store).unwrap(), b"\n", "the source tail is the newline after the last item");
}

crates/svc-core/tests/o1_round_trip.rs.Text:
use svc_core::RustLang;
use svc_core::engine::{ingest_file, lookup_name, relocate, render, rust_langs, snapshot_files};
use svc_core::ids::{ChangeId, RelPath};
use svc_core::lang::Langs;
use svc_core::store::MemStore;

fn round_trip(src: &str) -> String {
    let store = MemStore::new();
    let lang = RustLang;
    let path = RelPath::new("src/lib.rs").unwrap();
    let snap = ingest_file(src.as_bytes(), path, &lang, &store, ChangeId::new()).unwrap();
    let langs = Langs::new(vec![Box::new(RustLang)]);
    let rendered = render(&snap, &store, &langs, false).unwrap();
    let bytes = rendered.files.values().next().cloned().unwrap_or_default();
    String::from_utf8(bytes).unwrap()
}

#[test]
fn o1_simple_file() {
    let src = r#"struct Config { path: String }

fn read(path: &str) -> String {
    path.to_string()
}

fn main() {
    let _ = read("x");
}
"#;
    assert_eq!(round_trip(src), src);
}

#[test]
fn o1_impl_method() {
    let src = r#"struct Config;

impl Config {
    fn new() -> Self {
        Config
    }
}
"#;
    assert_eq!(round_trip(src), src);
}

#[test]
fn o1_use_and_trailing_newline() {
    let src = "use std::fmt;\n\nfn f() {}\n";
    assert_eq!(round_trip(src), src);
}

#[test]
fn o1_opaque_manifest_round_trips_without_a_language() {
    use std::collections::BTreeMap;
    let store = MemStore::new();
    let langs = rust_langs();
    let mut files = BTreeMap::new();
    files.insert(RelPath::new("src/lib.rs").unwrap(), b"fn f() {}\n".to_vec());
    files.insert(
        RelPath::new("Cargo.toml").unwrap(),
        b"[package]\nname = \"x\"\n".to_vec(),
    );
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let toml = RelPath::new("Cargo.toml").unwrap();
    assert_eq!(
        snap.files.get(&toml).unwrap().tail(&store).unwrap(),
        b"[package]\nname = \"x\"\n"
    );
    assert!(!snap.entities.values().any(|e| e.file == toml));
    let rendered = render(&snap, &store, &langs, false).unwrap();
    assert_eq!(
        rendered.files.get(&toml).unwrap().as_slice(),
        b"[package]\nname = \"x\"\n"
    );
}

#[test]
fn relocate_to_a_missing_path_is_still_rendered() {
    use std::collections::BTreeMap;
    let store = MemStore::new();
    let langs = rust_langs();
    let src = RelPath::new("src/lib.rs").unwrap();
    let dest = RelPath::new("src/b.rs").unwrap();
    let mut files = BTreeMap::new();
    files.insert(src.clone(), b"fn a() {}\nfn b() {}\n".to_vec());
    let snap = snapshot_files(&store, &langs, &files, None, ChangeId::new()).unwrap();
    let id = lookup_name(&snap, "b").unwrap();
    let next = relocate(&snap, &store, id, dest.clone(), 0).unwrap();
    assert!(
        next.files.contains_key(&dest),
        "relocate must create a FileRecord"
    );
    let rendered = render(&next, &store, &langs, false).unwrap();
    let dest_src = String::from_utf8_lossy(rendered.files.get(&dest).unwrap());
    assert!(dest_src.contains("fn b"), "{dest_src}");
    let src_src = String::from_utf8_lossy(rendered.files.get(&src).unwrap());
    assert!(!src_src.contains("fn b"), "{src_src}");
}

#[test]
fn o1_svc_core_source() {
    let root = std::path::Path::new(env!("CARGO_MANIFEST_DIR")).join("src");
    let mut files = Vec::new();
    visit(&root, &mut files);
    assert!(!files.is_empty());
    for path in files {
        let src = std::fs::read_to_string(&path).unwrap();
        let got = round_trip(&src);
        assert_eq!(got, src, "round-trip failed for {}", path.display());
    }
}

fn visit(dir: &std::path::Path, out: &mut Vec<std::path::PathBuf>) {
    for e in std::fs::read_dir(dir).unwrap() {
        let e = e.unwrap();
        let p = e.path();
        if p.is_dir() {
            visit(&p, out);
        } else if p.extension().and_then(|s| s.to_str()) == Some("rs") {
            out.push(p);
        }
    }
}
